#!/usr/bin/env bash
# prometheus-community/kube-state-metrics 7.4.0 - base variant: cluster-metrics-readonly
# Path: pull the package, render this base variant locally, read the objects,
# then apply them with kubectl. No ConfigHub account is needed.
# Generated by scripts/generate-public-site.mjs from the committed package
# data for this base variant. Chart page: https://confighub.github.io/helm-expt/site/charts/prometheus-community-kube-state-metrics-7-4-0.html
set -euo pipefail

say() { printf '\n>> %s\n' "$*"; }

if ! command -v cub >/dev/null 2>&1; then
  printf 'cub is not installed. Install the cub CLI with:\n  curl -fsSL https://hub.confighub.com/cub/install.sh | bash\nthen add ~/.confighub/bin to your PATH and re-run this script.\n' >&2
  exit 1
fi

# Installer is a cub plugin. Check it before this script does any work.
if ! cub installer --help >/dev/null 2>&1; then
  printf 'The cub installer plugin is missing. Follow https://confighub.github.io/helm-expt/site/try.html#install-cub, then re-run this script.\n' >&2
  exit 1
fi

if ! command -v kustomize >/dev/null 2>&1; then
  printf 'kustomize is missing. Follow https://confighub.github.io/helm-expt/site/try.html#install-cub, then re-run this script.\n' >&2
  exit 1
fi

if ! command -v kubectl >/dev/null 2>&1; then
  printf 'kubectl is required for the apply step.\n' >&2
  exit 1
fi

say "Pull the package and render the cluster-metrics-readonly base variant into ./prometheus-community-kube-state-metrics-7-4-0-cluster-metrics-readonly"
cub installer setup --pull oci://ghcr.io/confighub/packages/kube-state-metrics:v7.4.0@sha256:2e3c35170be8a38d360ef6fb8fae6859d8b01aa01bd34103b06c8c069d984de0 --base cluster-metrics-readonly --work-dir ./prometheus-community-kube-state-metrics-7-4-0-cluster-metrics-readonly --non-interactive --namespace default

say "Read what was rendered; nothing has touched the cluster yet"
ls ./prometheus-community-kube-state-metrics-7-4-0-cluster-metrics-readonly/out/manifests

say "Ensure the default namespace exists"
kubectl create namespace default --dry-run=client -o yaml | kubectl apply -f -

if [ -d ./prometheus-community-kube-state-metrics-7-4-0-cluster-metrics-readonly/out/secrets ]; then
  say "Apply rendered Secrets first"
  kubectl apply -f ./prometheus-community-kube-state-metrics-7-4-0-cluster-metrics-readonly/out/secrets
fi

say "Apply the rendered objects"
kubectl apply -f ./prometheus-community-kube-state-metrics-7-4-0-cluster-metrics-readonly/out/manifests

say "Done. The cluster received exactly the files in ./prometheus-community-kube-state-metrics-7-4-0-cluster-metrics-readonly/out."
